window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ad7c3016df059f69"]={"versions": [{"id": "FIG-ad7c3016df059f69", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Architektur- und Komponentendiagramm im Kontext der AUTOSAR Classic Platform (Virtual Function Bus / Basic Software). Das Diagramm illustriert das Konfigurations- und Verbindungsmuster für die Anbindung von Anwendungs-Software-Komponenten (SW-Cs) an den NVRAM Manager (NvM) über typisierte Service-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Komponentenentitäten und sechs Punkt-zu-Punkt-Portverbindungen:</p>\n<ul class=\"fig-list\">\n<li><strong>SW-C1: SWCTypeA</strong>: Erste Instanz des Software-Komponententyps <code>SWCTypeA</code> mit zwei Required Ports (<code>NVPort1</code>, <code>NVPort2</code>).</li>\n<li><strong>SW-C2: SWCTypeA</strong>: Zweite Instanz desselben Typs <code>SWCTypeA</code> mit identischen Required Ports (<code>NVPort1</code>, <code>NVPort2</code>).</li>\n<li><strong>SWC3: SWCTypeB</strong>: Instanz des Software-Komponententyps <code>SWCTypeB</code> mit zwei Required Ports (<code>NVPortX</code>, <code>NVPortY</code>).</li>\n<li><strong>NVRAMManager</strong>: Zentrales Basissoftware-Modul (BSW) mit sechs dedizierten Provided Service Ports (<code>PS2</code>, <code>PS3</code>, <code>PS4</code>, <code>PS5</code>, <code>PS6</code>, <code>PS7</code>).</li>\n<li><strong>Port-Kopplungen (Lollipop-Socket-Notation)</strong>:</li>\n<li><code>SW-C1:NVPort1</code> an <code>NVRAMManager:PS2</code></li>\n<li><code>SW-C1:NVPort2</code> an <code>NVRAMManager:PS3</code></li>\n<li><code>SW-C2:NVPort1</code> an <code>NVRAMManager:PS4</code></li>\n<li><code>SW-C2:NVPort2</code> an <code>NVRAMManager:PS5</code></li>\n<li><code>SWC3:NVPortX</code> an <code>NVRAMManager:PS6</code></li>\n<li><code>SWC3:NVPortY</code> an <code>NVRAMManager:PS7</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein strukturelles Schnittstellendiagramm enthält die Darstellung keine Kontrollfluss- oder Sequenzpfade. Zur Laufzeit initiieren die Software-Komponenten über die Client-Server-Schnittstellen der Service-Ports synchrone oder asynchrone NVRAM-Anfragen (wie Lese-, Schreib-, Wiederherstellungs- oder Invalidierungsoperationen für die zugeordneten NVRAM-Blöcke), die von der RTE an den NVRAM Manager weitergeleitet und verarbeitet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm demonstriert die normative Regelung zur Instanziierung und Service-Port-Bindung im AUTOSAR-Metamodell:</p>\n<ul class=\"fig-list\">\n<li>Multi-Instanz-Fähigkeit: Bei mehreren Instanzen desselben SW-C-Typs (<code>SW-C1</code>, <code>SW-C2</code>) referenzieren die typintern identisch benannten Required Ports (<code>NVPort1</code>, <code>NVPort2</code>) auf ECU-Ebene jeweils unterschiedliche, instanzspezifische Provide-Ports des NvM (<code>PS2</code>/<code>PS3</code> vs. <code>PS4</code>/<code>PS5</code>).</li>\n<li>1:1-Port-Zuordnung: Jeder NVRAM-Block bzw. dessen Service-Interface-Instanz im NVRAM Manager erfordert einen eigenen Service-Port (<code>PSx</code>), an den der entsprechende Client-Port der SW-C gebunden wird.</li>\n<li>Port-Kompatibilität: Client- und Server-Ports müssen hinsichtlich Interface-Typ und Operationen kompatibel konfiguriert sein (gemäß AUTOSAR VFB-Spezifikation).</li>\n</ul>"}, {"id": "FIG-581c939c4334f94d", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Architektur- und Komponentendiagramm im Kontext der AUTOSAR Classic Platform (Virtual Function Bus / Basic Software). Das Diagramm illustriert das Konfigurations- und Verbindungsmuster für die Anbindung von Anwendungs-Software-Komponenten (SW-Cs) an den NVRAM Manager (NvM) über typisierte Service-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Komponentenentitäten und sechs Punkt-zu-Punkt-Portverbindungen:</p>\n<ul class=\"fig-list\">\n<li><strong>SW-C1: SWCTypeA</strong>: Erste Instanz des Software-Komponententyps <code>SWCTypeA</code> mit zwei Required Ports (<code>NVPort1</code>, <code>NVPort2</code>).</li>\n<li><strong>SW-C2: SWCTypeA</strong>: Zweite Instanz desselben Typs <code>SWCTypeA</code> mit identischen Required Ports (<code>NVPort1</code>, <code>NVPort2</code>).</li>\n<li><strong>SWC3: SWCTypeB</strong>: Instanz des Software-Komponententyps <code>SWCTypeB</code> mit zwei Required Ports (<code>NVPortX</code>, <code>NVPortY</code>).</li>\n<li><strong>NVRAMManager</strong>: Zentrales Basissoftware-Modul (BSW) mit sechs dedizierten Provided Service Ports (<code>PS2</code>, <code>PS3</code>, <code>PS4</code>, <code>PS5</code>, <code>PS6</code>, <code>PS7</code>).</li>\n<li><strong>Port-Kopplungen (Lollipop-Socket-Notation)</strong>:</li>\n<li><code>SW-C1:NVPort1</code> an <code>NVRAMManager:PS2</code></li>\n<li><code>SW-C1:NVPort2</code> an <code>NVRAMManager:PS3</code></li>\n<li><code>SW-C2:NVPort1</code> an <code>NVRAMManager:PS4</code></li>\n<li><code>SW-C2:NVPort2</code> an <code>NVRAMManager:PS5</code></li>\n<li><code>SWC3:NVPortX</code> an <code>NVRAMManager:PS6</code></li>\n<li><code>SWC3:NVPortY</code> an <code>NVRAMManager:PS7</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein strukturelles Schnittstellendiagramm enthält die Darstellung keine Kontrollfluss- oder Sequenzpfade. Zur Laufzeit initiieren die Software-Komponenten über die Client-Server-Schnittstellen der Service-Ports synchrone oder asynchrone NVRAM-Anfragen (wie Lese-, Schreib-, Wiederherstellungs- oder Invalidierungsoperationen für die zugeordneten NVRAM-Blöcke), die von der RTE an den NVRAM Manager weitergeleitet und verarbeitet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm demonstriert die normative Regelung zur Instanziierung und Service-Port-Bindung im AUTOSAR-Metamodell:</p>\n<ul class=\"fig-list\">\n<li>Multi-Instanz-Fähigkeit: Bei mehreren Instanzen desselben SW-C-Typs (<code>SW-C1</code>, <code>SW-C2</code>) referenzieren die typintern identisch benannten Required Ports (<code>NVPort1</code>, <code>NVPort2</code>) auf ECU-Ebene jeweils unterschiedliche, instanzspezifische Provide-Ports des NvM (<code>PS2</code>/<code>PS3</code> vs. <code>PS4</code>/<code>PS5</code>).</li>\n<li>1:1-Port-Zuordnung: Jeder NVRAM-Block bzw. dessen Service-Interface-Instanz im NVRAM Manager erfordert einen eigenen Service-Port (<code>PSx</code>), an den der entsprechende Client-Port der SW-C gebunden wird.</li>\n<li>Port-Kompatibilität: Client- und Server-Ports müssen hinsichtlich Interface-Typ und Operationen kompatibel konfiguriert sein (gemäß AUTOSAR VFB-Spezifikation).</li>\n</ul>"}, {"id": "FIG-50da7898f72d3828", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Architektur- und Komponentendiagramm im Kontext der AUTOSAR Classic Platform (Virtual Function Bus / Basic Software). Das Diagramm illustriert das Konfigurations- und Verbindungsmuster für die Anbindung von Anwendungs-Software-Komponenten (SW-Cs) an den NVRAM Manager (NvM) über typisierte Service-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier Komponentenentitäten und sechs Punkt-zu-Punkt-Portverbindungen:</p>\n<ul class=\"fig-list\">\n<li><strong>SW-C1: SWCTypeA</strong>: Erste Instanz des Software-Komponententyps <code>SWCTypeA</code> mit zwei Required Ports (<code>NVPort1</code>, <code>NVPort2</code>).</li>\n<li><strong>SW-C2: SWCTypeA</strong>: Zweite Instanz desselben Typs <code>SWCTypeA</code> mit identischen Required Ports (<code>NVPort1</code>, <code>NVPort2</code>).</li>\n<li><strong>SWC3: SWCTypeB</strong>: Instanz des Software-Komponententyps <code>SWCTypeB</code> mit zwei Required Ports (<code>NVPortX</code>, <code>NVPortY</code>).</li>\n<li><strong>NVRAMManager</strong>: Zentrales Basissoftware-Modul (BSW) mit sechs dedizierten Provided Service Ports (<code>PS2</code>, <code>PS3</code>, <code>PS4</code>, <code>PS5</code>, <code>PS6</code>, <code>PS7</code>).</li>\n<li><strong>Port-Kopplungen (Lollipop-Socket-Notation)</strong>:</li>\n<li><code>SW-C1:NVPort1</code> an <code>NVRAMManager:PS2</code></li>\n<li><code>SW-C1:NVPort2</code> an <code>NVRAMManager:PS3</code></li>\n<li><code>SW-C2:NVPort1</code> an <code>NVRAMManager:PS4</code></li>\n<li><code>SW-C2:NVPort2</code> an <code>NVRAMManager:PS5</code></li>\n<li><code>SWC3:NVPortX</code> an <code>NVRAMManager:PS6</code></li>\n<li><code>SWC3:NVPortY</code> an <code>NVRAMManager:PS7</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein strukturelles Schnittstellendiagramm enthält die Darstellung keine Kontrollfluss- oder Sequenzpfade. Zur Laufzeit initiieren die Software-Komponenten über die Client-Server-Schnittstellen der Service-Ports synchrone oder asynchrone NVRAM-Anfragen (wie Lese-, Schreib-, Wiederherstellungs- oder Invalidierungsoperationen für die zugeordneten NVRAM-Blöcke), die von der RTE an den NVRAM Manager weitergeleitet und verarbeitet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm demonstriert die normative Regelung zur Instanziierung und Service-Port-Bindung im AUTOSAR-Metamodell:</p>\n<ul class=\"fig-list\">\n<li>Multi-Instanz-Fähigkeit: Bei mehreren Instanzen desselben SW-C-Typs (<code>SW-C1</code>, <code>SW-C2</code>) referenzieren die typintern identisch benannten Required Ports (<code>NVPort1</code>, <code>NVPort2</code>) auf ECU-Ebene jeweils unterschiedliche, instanzspezifische Provide-Ports des NvM (<code>PS2</code>/<code>PS3</code> vs. <code>PS4</code>/<code>PS5</code>).</li>\n<li>1:1-Port-Zuordnung: Jeder NVRAM-Block bzw. dessen Service-Interface-Instanz im NVRAM Manager erfordert einen eigenen Service-Port (<code>PSx</code>), an den der entsprechende Client-Port der SW-C gebunden wird.</li>\n<li>Port-Kompatibilität: Client- und Server-Ports müssen hinsichtlich Interface-Typ und Operationen kompatibel konfiguriert sein (gemäß AUTOSAR VFB-Spezifikation).</li>\n</ul>"}], "trans": [{"from": "FIG-ad7c3016df059f69", "to": "FIG-581c939c4334f94d", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-581c939c4334f94d", "to": "FIG-50da7898f72d3828", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
